ST.xhtml:p:
IF Not g_bLaserDotEnable THEN
  g_boMainChuckBlowing := g_bLaserCuttingEnable;
END_IF;
RTriggerSignalClaw1Control(CLK := g_biExternalSignalClaw1);
RTriggerSignalClaw2Control(CLK := g_biExternalSignalClaw2);
IF RTriggerSignalClaw1Control.Q THEN
  IF g_nPlcState <> 1 THEN
    IF g_bBackClawState THEN
      g_bClaw1EnableOff := TRUE;
       g_bClaw1Enable := FALSE;
    ELSE
      g_bClaw1Enable := TRUE;
      g_bClaw1EnableOff := FALSE;
    END_IF;
  END_IF;
END_IF;
IF RTriggerSignalClaw2Control.Q THEN
  IF g_nPlcState <> 1 THEN
    IF g_bFrontClawState THEN
      g_bClaw2EnableOff := TRUE;
      g_bClaw2Enable := FALSE;
    ELSE
      g_bClaw2Enable := TRUE;
      g_bClaw2EnableOff := FALSE;
    END_IF;
  END_IF;
END_IF;

Rtring_CylinderControlM(CLK := g_bSupportCylinderControlM OR bCylinderControl);
bSupportCyl1AvoidState :=  g_fCurrentCoordYBuffer>=g_fClylinder1CoordY-g_fClylinder1DownDistance AND NOT g_bSupportCylinder1ShieldFlag; 
bSupportCyl2AvoidState := g_fCurrentCoordYBuffer>=g_fClylinder2CoordY-g_fClylinder2DownDistance AND NOT g_bSupportCylinder2ShieldFlag;
bSupportCyl3AvoidState := g_fCurrentCoordYBuffer>=g_fClylinder3CoordY-g_fClylinder3DownDistance AND NOT g_bSupportCylinder3ShieldFlag;
bSupportCyl4AvoidState := g_fCurrentCoordYBuffer>=g_fClylinder4CoordY-g_fClylinder4DownDistance AND NOT g_bSupportCylinder4ShieldFlag; 
bSupportCyl5AvoidState := g_fCurrentCoordYBuffer>=g_fClylinder5CoordY-g_fClylinder5DownDistance AND NOT g_bSupportCylinder5ShieldFlag; 
bSupportCyl6AvoidState := g_fCurrentCoordYBuffer>=g_fClylinder6CoordY-g_fClylinder6DownDistance AND NOT g_bSupportCylinder6ShieldFlag; 
bSupportCyl7AvoidState := g_fCurrentCoordYBuffer>=g_fClylinder7CoordY-g_fClylinder7DownDistance AND NOT g_bSupportCylinder7ShieldFlag; 
bSupportCyl8AvoidState := g_fCurrentCoordYBuffer>=g_fClylinder8CoordY-g_fClylinder8DownDistance AND NOT g_bSupportCylinder8ShieldFlag; 
bSupportCyl9AvoidState := g_fCurrentCoordYBuffer>=g_fClylinder9CoordY-g_fClylinder9DownDistance AND NOT g_bSupportCylinder9ShieldFlag; 
bSupportCyl10AvoidState := g_fCurrentCoordYBuffer>=g_fClylinder10CoordY-g_fClylinder10DownDistance AND NOT g_bSupportCylinder10ShieldFlag;
bSupportCyl11AvoidState := g_fCurrentCoordYBuffer>=g_fClylinder11CoordY-g_fClylinder11DownDistance AND NOT g_bSupportCylinder11ShieldFlag;
bSupportCyl12AvoidState := g_fCurrentCoordYBuffer>=g_fClylinder12CoordY-g_fClylinder12DownDistance AND NOT g_bSupportCylinder12ShieldFlag;

IF Rtring_CylinderControlM.Q THEN
  IF g_bSupportCylinderControlM THEN
    dSupportCylinderIndex := M.PARAMETER_P[264];
    dSupportCylinderType := M.PARAMETER_Q[264];
  END_IF;
  IF dSupportCylinderType = 1.0 THEN
    IF dSupportCylinderIndex = 0.0 THEN
      nSupportCylinder1MState := 10;
    ELSIF dSupportCylinderIndex = 1.0 THEN
      nSupportCylinder2MState := 10;
    ELSIF dSupportCylinderIndex = 2.0 THEN
      nSupportCylinder3MState := 10;
    ELSIF dSupportCylinderIndex = 3.0 THEN
      nSupportCylinder4MState := 10;
    ELSIF dSupportCylinderIndex = 4.0 THEN
      nSupportCylinder5MState := 10;
    ELSIF dSupportCylinderIndex= 5.0 THEN
      nSupportCylinder6MState := 10;
    ELSIF dSupportCylinderIndex = 6.0 THEN
      nSupportCylinder7MState := 10;
    ELSIF dSupportCylinderIndex = 7.0 THEN
      nSupportCylinder8MState := 10;
    ELSIF dSupportCylinderIndex = 8.0 THEN (*8特殊,处理全部气缸*)
      nSupportCylinder100MState := 10;
    ELSIF dSupportCylinderIndex = 9.0 THEN
      nSupportCylinder9MState := 10;
    ELSIF dSupportCylinderIndex = 10.0 THEN
      nSupportCylinder10MState := 10;
    ELSIF dSupportCylinderIndex = 11.0 THEN
      nSupportCylinder11MState := 10;
    ELSIF dSupportCylinderIndex = 12.0 THEN
      nSupportCylinder12MState := 10;
    END_IF;
  ELSE
    IF dSupportCylinderIndex = 0.0 THEN
      nSupportCylinder1MState := 50;
    ELSIF dSupportCylinderIndex = 1.0 THEN
      nSupportCylinder2MState := 50;
    ELSIF dSupportCylinderIndex = 2.0 THEN
      nSupportCylinder3MState := 50;
    ELSIF dSupportCylinderIndex = 3.0 THEN
      nSupportCylinder4MState := 50;
    ELSIF dSupportCylinderIndex = 4.0 THEN
      nSupportCylinder5MState := 50;
    ELSIF dSupportCylinderIndex= 5.0 THEN
      nSupportCylinder6MState := 50;
    ELSIF dSupportCylinderIndex = 6.0 THEN
      nSupportCylinder7MState := 50;
    ELSIF dSupportCylinderIndex = 7.0 THEN
      nSupportCylinder8MState := 50;
    ELSIF dSupportCylinderIndex = 8.0 THEN(*8特殊,处理全部气缸*)
      nSupportCylinder100MState := 50;
    ELSIF dSupportCylinderIndex = 9.0 THEN
      nSupportCylinder9MState := 50; 
    ELSIF dSupportCylinderIndex = 10.0 THEN
      nSupportCylinder10MState := 50; 
    ELSIF dSupportCylinderIndex = 11.0 THEN
      nSupportCylinder11MState := 50; 
    ELSIF dSupportCylinderIndex = 12.0 THEN
      nSupportCylinder12MState := 50; 
    END_IF;
  END_IF;
    g_bSupportCylinderControlM := FALSE;
    bCylinderControl := FALSE;
END_IF;

(*9个状态机可以后期简化成调用一个功能块*)
CASE nSupportCylinder1MState OF 
  0:
    nSupportCylinder1MState := 0;
  10:(*下降*)
    g_bSupportcyLinder1Enable := FALSE;
    g_bSupportcyLinder1Down := TRUE;
    nSupportCylinder1MState := 20;
  20:(*等待到位*)
    IF NOT g_bClylinder1State THEN
      M.ENABLE[264] := 0;
      g_bExecuteFinishedM264 := FALSE;
      g_bFinishedM264_0 := FALSE;
      nSupportCylinder1MState := 0;
    END_IF;
  50:(*上升*)
    nSupportCylinder1MState := 60;
    g_bSupportcyLinder1Down := FALSE;
    g_bSupportcyLinder1Enable := TRUE;
    IF bSupportCyl1AvoidState THEN
      g_bSupportcyLinder1Enable := FALSE;
      M.ENABLE[264] := 0;
      g_bExecuteFinishedM264 := FALSE;
      g_bFinishedM264_0 := FALSE;
      nSupportCylinder1MState := 0;
    END_IF;

  60:
    IF g_bClylinder1State THEN
      M.ENABLE[264] := 0;
      g_bExecuteFinishedM264 := FALSE;
      g_bFinishedM264_0 := FALSE;
      nSupportCylinder1MState := 0;
    END_IF;

END_CASE;

