CASE nSupportCylinder100MState OF
  0:
    nSupportCylinder100MState := 0;
  10:(*下降*)
    IF g_nClylinderCount = 0 THEN
      g_boSustainUpDownDone := TRUE;
      g_bSustainUpDownDone := TRUE;
      nSupportCylinder100MState := 0;
      M.ENABLE[264] := 0;
      g_bExecuteFinishedM264 := FALSE;
      g_bFinishedM264_9 := FALSE;
    ELSE
      IF g_nClylinderCount >= 1 THEN
		g_bSupportcyLinder1Down := TRUE;
      END_IF;
      IF g_nClylinderCount >= 2 THEN
		g_bSupportcyLinder2Down := TRUE;
      END_IF;
      IF g_nClylinderCount >= 3 THEN
        g_bSupportcyLinder3Down := TRUE;
      END_IF;
      IF g_nClylinderCount >= 4 THEN
        g_bSupportcyLinder4Down := TRUE;
      END_IF;
      IF g_nClylinderCount >= 5 THEN
        g_bSupportcyLinder5Down := TRUE;
      END_IF;
      IF g_nClylinderCount >= 6 THEN
        g_bSupportcyLinder6Down := TRUE;
      END_IF;
      IF g_nClylinderCount >= 7 THEN
        g_bSupportcyLinder7Down := TRUE;
      END_IF;
      IF g_nClylinderCount >= 8 THEN
        g_bSupportcyLinder8Down := TRUE;
      END_IF;
      IF g_nClylinderCount >= 9 THEN
        g_bSupportcyLinder9Down := TRUE;
      END_IF;
      IF g_nClylinderCount >= 10 THEN
        g_bSupportcyLinder10Down := TRUE;
      END_IF;
      IF g_nClylinderCount >= 11 THEN
        g_bSupportcyLinder11Down := TRUE;
      END_IF;
      IF g_nClylinderCount >= 12 THEN
        g_bSupportcyLinder12Down := TRUE;
      END_IF;
      nSupportCylinder100MState := 15;
    END_IF;
  15:(*等待下降到位*)
    bCheckFlag := TRUE;
    IF g_nClylinderCount >= 1 AND g_boSupportcyLinder1DownEnable AND g_bClylinder1State THEN
      bCheckFlag := FALSE; 
    END_IF;
    IF g_nClylinderCount >= 2 AND g_boSupportcyLinder2DownEnable AND g_bClylinder2State THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 3 AND g_boSupportcyLinder3DownEnable AND g_bClylinder3State THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 4 AND g_boSupportcyLinder4DownEnable AND g_bClylinder4State THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 5 AND g_boSupportcyLinder5DownEnable AND g_bClylinder5State THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 6 AND g_boSupportcyLinder6DownEnable AND g_bClylinder6State THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 7 AND g_boSupportcyLinder7DownEnable AND g_bClylinder7State THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 8 AND g_boSupportcyLinder8DownEnable AND g_bClylinder8State THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 9 AND g_boSupportcyLinder9DownEnable AND g_bClylinder9State THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 10 AND g_boSupportcyLinder10DownEnable AND g_bClylinder10State THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 11 AND g_boSupportcyLinder11DownEnable AND g_bClylinder11State THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 12 AND g_boSupportcyLinder12DownEnable AND g_bClylinder12State THEN
      bCheckFlag := FALSE;
    END_IF;
    IF bCheckFlag THEN
      nSupportCylinder100MState := 100;
    END_IF;
  50:
    IF g_nClylinderCount = 0 THEN
      g_boSustainUpDownDone := TRUE;
      g_bSustainUpDownDone := TRUE;
      nSupportCylinder100MState := 0;
      M.ENABLE[264] := 0;
      g_bExecuteFinishedM264 := FALSE;
      g_bFinishedM264_9 := FALSE;
    ELSE
      IF g_nClylinderCount >= 1  THEN
        g_bSupportcyLinder1Enable := TRUE;
      END_IF;
      IF g_nClylinderCount >= 2  THEN
        g_bSupportcyLinder2Enable := TRUE;
      END_IF;
      IF g_nClylinderCount >= 3  THEN
        g_bSupportcyLinder3Enable := TRUE;
      END_IF;
      IF g_nClylinderCount >= 4 THEN
        g_bSupportcyLinder4Enable := TRUE;
      END_IF;
      IF g_nClylinderCount >= 5 THEN
        g_bSupportcyLinder5Enable := TRUE;
      END_IF;
      IF g_nClylinderCount >= 6 THEN
        g_bSupportcyLinder6Enable := TRUE;
      END_IF;
      IF g_nClylinderCount >= 7 THEN
        g_bSupportcyLinder7Enable := TRUE;
      END_IF;
      IF g_nClylinderCount >= 8 THEN
        g_bSupportcyLinder8Enable := TRUE;
      END_IF;
      IF g_nClylinderCount >= 9 THEN
        g_bSupportcyLinder9Enable := TRUE;
      END_IF;
      IF g_nClylinderCount >= 10 THEN
        g_bSupportcyLinder10Enable := TRUE;
      END_IF;
      IF g_nClylinderCount >= 11 THEN
        g_bSupportcyLinder11Enable := TRUE;
      END_IF;
      IF g_nClylinderCount >= 12 THEN
        g_bSupportcyLinder12Enable := TRUE;
      END_IF;
      nSupportCylinder100MState := 55;
    END_IF;
  55:
    bCheckFlag := TRUE;
    IF g_nClylinderCount >= 1 AND g_boSupportcyLinder1UpEnable AND (NOT g_bClylinder1State) AND NOT bSupportCyl1AvoidState THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 2 AND g_boSupportcyLinder2UpEnable AND (NOT g_bClylinder2State) AND NOT bSupportCyl2AvoidState THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 3 AND g_boSupportcyLinder3UpEnable AND (NOT g_bClylinder3State) AND NOT bSupportCyl3AvoidState THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 4 AND g_boSupportcyLinder4UpEnable AND (NOT g_bClylinder4State) AND NOT bSupportCyl4AvoidState THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 5 AND g_boSupportcyLinder5UpEnable AND (NOT g_bClylinder5State) AND NOT bSupportCyl5AvoidState THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 6 AND g_boSupportcyLinder6UpEnable AND (NOT g_bClylinder6State) AND NOT bSupportCyl6AvoidState THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 7 AND g_boSupportcyLinder7UpEnable AND (NOT g_bClylinder7State) AND NOT bSupportCyl7AvoidState THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 8 AND g_boSupportcyLinder8UpEnable AND (NOT g_bClylinder8State) AND NOT bSupportCyl8AvoidState THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 9 AND g_boSupportcyLinder9UpEnable AND (NOT g_bClylinder9State) AND NOT bSupportCyl9AvoidState THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 10 AND g_boSupportcyLinder10UpEnable AND (NOT g_bClylinder10State) AND NOT bSupportCyl10AvoidState THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 11 AND g_boSupportcyLinder11UpEnable AND (NOT g_bClylinder11State) AND NOT bSupportCyl11AvoidState THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nClylinderCount >= 12 AND g_boSupportcyLinder12UpEnable AND (NOT g_bClylinder12State) AND NOT bSupportCyl12AvoidState THEN
      bCheckFlag := FALSE;
    END_IF;
    IF bCheckFlag THEN
      nSupportCylinder100MState := 100;
    END_IF;
  100:
    g_bSupportcyLinder1Enable := FALSE;
    g_bSupportcyLinder2Enable := FALSE;
    g_bSupportcyLinder3Enable := FALSE;
    g_bSupportcyLinder4Enable := FALSE;
    g_bSupportcyLinder5Enable := FALSE;
    g_bSupportcyLinder6Enable := FALSE;
    g_bSupportcyLinder7Enable := FALSE;
    g_bSupportcyLinder8Enable := FALSE;
    g_bSupportcyLinder9Enable := FALSE;
    g_bSupportcyLinder10Enable := FALSE;
    g_bSupportcyLinder11Enable := FALSE;
    g_bSupportcyLinder12Enable := FALSE;
    g_bSupportcyLinder1Down := FALSE;
    g_bSupportcyLinder2Down := FALSE;
    g_bSupportcyLinder3Down := FALSE;
    g_bSupportcyLinder4Down := FALSE;
    g_bSupportcyLinder5Down := FALSE;
    g_bSupportcyLinder6Down := FALSE;
    g_bSupportcyLinder7Down := FALSE;
    g_bSupportcyLinder8Down := FALSE;
    g_bSupportcyLinder9Down := FALSE;
    g_bSupportcyLinder10Down := FALSE;
    g_bSupportcyLinder11Down := FALSE;
    g_bSupportcyLinder12Down := FALSE;
    g_boSustainUpDownDone := TRUE;
    g_bSustainUpDownDone := TRUE;
    nSupportCylinder100MState := 0;
    M.ENABLE[264] := 0;
    g_bExecuteFinishedM264 := FALSE;
    g_bFinishedM264_9 := FALSE;
END_CASE;

RtrigClaw1(CLK := ( g_bClaw1EnableM OR g_bClaw1Enable OR bClaw1Enable OR g_biClaw1Enable));
RtrigClaw10ff(CLK := ( g_bClaw1EnableOffM OR g_bClaw1EnableOff OR bClaw1EnableOff OR g_biClaw1EnableOff));
(*气缸上升信号检测*)
RtringSupportcyLinder1Up(CLK :=(g_biSupportcyLinder1Enable OR g_bSupportcyLinder1Enable OR bSupportcyLinder1Enable));
RtringSupportcyLinder2Up(CLK :=(g_biSupportcyLinder2Enable OR g_bSupportcyLinder2Enable OR bSupportcyLinder2Enable));
RtringSupportcyLinder3Up(CLK :=(g_biSupportcyLinder3Enable OR g_bSupportcyLinder3Enable OR bSupportcyLinder3Enable));
RtringSupportcyLinder4Up(CLK :=(g_biSupportcyLinder4Enable OR g_bSupportcyLinder4Enable OR bSupportcyLinder4Enable));
RtringSupportcyLinder5Up(CLK :=(g_biSupportcyLinder5Enable OR g_bSupportcyLinder5Enable OR bSupportcyLinder5Enable));
RtringSupportcyLinder6Up(CLK :=(g_biSupportcyLinder6Enable OR g_bSupportcyLinder6Enable OR bSupportcyLinder6Enable));
RtringSupportcyLinder7Up(CLK :=(g_biSupportcyLinder7Enable OR g_bSupportcyLinder7Enable OR bSupportcyLinder7Enable));
RtringSupportcyLinder8Up(CLK :=(g_biSupportcyLinder8Enable OR g_bSupportcyLinder8Enable OR bSupportcyLinder8Enable));
RtringSupportcyLinder9Up(CLK :=(g_biSupportcyLinder9Enable OR g_bSupportcyLinder9Enable OR bSupportcyLinder9Enable));
RtringSupportcyLinder10Up(CLK :=(g_biSupportcyLinder10Enable OR g_bSupportcyLinder10Enable OR bSupportcyLinder10Enable));
RtringSupportcyLinder11Up(CLK :=(g_biSupportcyLinder11Enable OR g_bSupportcyLinder11Enable OR bSupportcyLinder11Enable));
RtringSupportcyLinder12Up(CLK :=(g_biSupportcyLinder12Enable OR g_bSupportcyLinder12Enable OR bSupportcyLinder12Enable));
(*气缸下降信号检测*)
RtringSupportcyLinder1Down(CLK :=(g_biSupportcyLinder1DownEnable OR g_bSupportcyLinder1Down OR bSupportcyLinder1Down));
RtringSupportcyLinder2Down(CLK := (g_biSupportcyLinder2DownEnable OR g_bSupportcyLinder2Down OR bSupportcyLinder2Down));
RtringSupportcyLinder3Down(CLK := (g_biSupportcyLinder3DownEnable OR g_bSupportcyLinder3Down OR bSupportcyLinder3Down));
RtringSupportcyLinder4Down(CLK := (g_biSupportcyLinder4DownEnable OR g_bSupportcyLinder4Down OR bSupportcyLinder4Down));
RtringSupportcyLinder5Down(CLK := (g_biSupportcyLinder5DownEnable OR g_bSupportcyLinder5Down OR bSupportcyLinder5Down));
RtringSupportcyLinder6Down(CLK := (g_biSupportcyLinder6DownEnable OR g_bSupportcyLinder6Down OR bSupportcyLinder6Down));
RtringSupportcyLinder7Down(CLK := (g_biSupportcyLinder7DownEnable OR g_bSupportcyLinder7Down OR bSupportcyLinder7Down));
RtringSupportcyLinder8Down(CLK := (g_biSupportcyLinder8DownEnable OR g_bSupportcyLinder8Down OR bSupportcyLinder8Down));
RtringSupportcyLinder9Down(CLK := (g_biSupportcyLinder9DownEnable OR g_bSupportcyLinder9Down OR bSupportcyLinder9Down));
RtringSupportcyLinder10Down(CLK := (g_biSupportcyLinder10DownEnable OR g_bSupportcyLinder10Down OR bSupportcyLinder10Down));
RtringSupportcyLinder11Down(CLK := (g_biSupportcyLinder11DownEnable OR g_bSupportcyLinder11Down OR bSupportcyLinder11Down));
RtringSupportcyLinder12Down(CLK := (g_biSupportcyLinder12DownEnable OR g_bSupportcyLinder12Down OR bSupportcyLinder12Down));




(*卡爪1-后卡松紧开关*)
IF RtrigClaw1.Q THEN(*夹紧操作：先上下夹紧，延时时间后左右夹紧*)
  IF g_biClaw1Enable AND g_nPlcState = 1 THEN
    RETURN;
  END_IF;
  IF g_dM197SetKValue = 1.0 AND g_bBackCardIsJiaJin THEN
		g_boClaw1Done:=TRUE;
		M.ENABLE[197] := 0;
		g_bExecuteFinishedM197 := FALSE;
		g_bFinishedM197_0 := FALSE;
         g_bClaw1Enable:=FALSE;(*资源回收*)
		g_bClaw1EnableM := FALSE;
		bClaw1Enable:=FALSE;
		RETURN;
  END_IF;
    nClaw1ChangeState:=10;
    g_boClaw1Done:=FALSE;
    g_bClaw1State:= TRUE;
    nTonClaw1Keep(IN :=FALSE);
    g_bClaw1Enable:=FALSE;(*资源回收*)
    g_bClaw1EnableM := FALSE;
    bClaw1Enable:=FALSE;
    bClaw1UpDownClampFlag := FALSE;
    bClaw1LeftRightClampFlag := FALSE;
    Claw1ClampTon(IN :=FALSE);
    nTonClaw1Keep(IN :=FALSE);
    InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);
    bForbidBackCardClawCylDownNoSignalAlarm:= FALSE;
    bUseForbidBackCardClawCylUpFlag:= TRUE;
    bUseForbidBackCardClawCylDownFlag:= FALSE;
END_IF;

IF RtrigClaw10ff.Q THEN
  IF g_biClaw1EnableOff AND g_nPlcState = 1 THEN
    RETURN;
  END_IF;
  (*后卡禁止松开*)
 IF g_bForbidBackCardLossenExceedSetYPos AND g_fCurrentCoordYBuffer > g_dSetBackCardYCoord THEN
    g_boClaw1Done:=TRUE;
    IF NOT g_bAllClawCylControlFlagM THEN
      M.ENABLE[197] := 0;
      g_bExecuteFinishedM197 := FALSE;
      g_bFinishedM197_0 := FALSE;
    END_IF;
    g_bClaw1EnableOff:=FALSE;(*资源回收*)
    bClaw1EnableOff:=FALSE;
    g_bClaw1EnableOffM := FALSE;
  RETURN;
  END_IF;
  IF g_dM197SetKValue = 1.0 AND NOT g_bBackCardIsJiaJin THEN
		g_boClaw1Done:=TRUE;
		M.ENABLE[197] := 0;
		g_bExecuteFinishedM197 := FALSE;
		g_bFinishedM197_0 := FALSE;
        g_bClaw1EnableOff:=FALSE;(*资源回收*)
		bClaw1EnableOff:=FALSE;
        g_bClaw1EnableOffM := FALSE;
    RETURN;
  END_IF;
      nClaw1ChangeState:=50;
      g_bClaw1EnableOff:=FALSE;(*资源回收*)
      bClaw1EnableOff:=FALSE;
      nTonClaw1Keep(IN :=FALSE);
      g_boClaw1Done:=FALSE;
      g_bClaw1State:= FALSE;
      g_bClaw1EnableOffM := FALSE;
      bClaw1UpDownClampFlag := FALSE;
      bClaw1LeftRightClampFlag := FALSE;
      Claw1InPlaceTon(IN :=FALSE);
      nTonClaw1Keep(IN :=FALSE);
      bChuck1OperatedLoosen := TRUE;
      InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE);
      bForbidBackCardClawCylUpNoSignalAlarm:= FALSE;
      bUseForbidBackCardClawCylUpFlag:= FALSE;
      bUseForbidBackCardClawCylDownFlag:= TRUE;
END_IF;
(*卡爪1状态*)

(*单io *)
IF g_nClamp2ControlType = 1 THEN
  CASE nClaw1ChangeState OF
    0:
      nClaw1ChangeState:=0;
    10:
      g_noClaw1GasControl :=FUN_pressureCovertAO(dSetGasPersent*g_nClawMaxPressure,g_nClawMaxPressure,g_nClawMaxVoltage);    
      g_boClaw1UpDownClampEnable :=TRUE; 
      g_boClaw1UpDownLoosenEnable:= FALSE;
      IF bKeepPressure THEN
        bClaw1KeepPressureDone :=FALSE;
        nClaw1KeepPressureState := 10; 
      ELSE
        bClaw1KeepPressureDone :=TRUE; 
      END_IF;
      nClaw1ChangeState:=20; 
      bClaw1UpDownClampFlag := TRUE;
      bClaw1UpDownLoosenFlag := FALSE;
    20:
      IF g_bBackCardUseUpDownClampInplaceSignal THEN
        IF g_bUpDownClampedInPlaceClaw1 THEN  
          nClaw1ChangeState:=150; 
          InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE);
          bForbidBackCardClawCylUpNoSignalAlarm:= FALSE;
        ELSE
          IF NOT g_bBackClawState THEN
            InPlaceForbidBackCardClawUpDelayAlarm(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_dBackCardUpDownClampInplaceDelay)));
            IF InPlaceForbidBackCardClawUpDelayAlarm.Q THEN
              bForbidBackCardClawCylUpNoSignalAlarm:= TRUE;
              InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE);
            END_IF;
          ELSE
            bForbidBackCardClawCylUpNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE);     
          END_IF; 
        END_IF;
      ELSE
        Claw1ClampTon(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(g_dBackCardUpDownClampInplaceDelay)));
        IF Claw1ClampTon.Q THEN
          nClaw1ChangeState:=150;
          Claw1ClampTon(IN :=FALSE);
        END_IF;
      END_IF;
    50:
      g_noClaw1GasControl :=FUN_pressureCovertAO(g_nClawMaxPressure,g_nClawMaxPressure,g_nClawMaxVoltage);
      g_boClaw1UpDownClampEnable:=FALSE;   
      g_boClaw1UpDownLoosenEnable :=TRUE;
      IF bKeepPressure THEN
        bClaw1KeepPressureDone :=FALSE;
        nClaw1KeepPressureState := 10;
      ELSE
        bClaw1KeepPressureDone :=TRUE;   
      END_IF; 
      nClaw1ChangeState:=60; 
      bClaw1UpDownClampFlag := FALSE;
      bClaw1UpDownLoosenFlag := TRUE;
    60:
      IF g_bBackCardUseUpDownLossenInplaceSignal THEN
        IF g_bUpDownLossendInPlaceClaw1 THEN
          nClaw1ChangeState := 150;
          InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);
          bForbidBackCardClawCylDownNoSignalAlarm:= FALSE;
        ELSE
          IF g_bBackClawState THEN
            InPlaceForbidBackCardClawDownDelayAlarm(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_dBackCardUpDownClampInplaceDelay)));
            IF InPlaceForbidBackCardClawDownDelayAlarm.Q THEN
              bForbidBackCardClawCylDownNoSignalAlarm:= TRUE;
              InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);
            END_IF;
          ELSE
            bForbidBackCardClawCylDownNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);     
          END_IF; 
        END_IF;
      ELSE
        Claw1InPlaceTon(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(g_dBackCardUpDownLossenInplaceDelay)));
        IF Claw1InPlaceTon.Q THEN
          nClaw1ChangeState := 150;
          Claw1InPlaceTon(IN :=FALSE);
        END_IF;
      END_IF;  
    150:  
      IF bClaw1KeepPressureDone THEN
        bClaw1KeepPressureDone :=FALSE;
        nClaw1ChangeState:=0;
        g_boClaw1Done:=TRUE;
        IF NOT g_bAllClawCylControlFlagM THEN
          M.ENABLE[197] := 0;
          g_bExecuteFinishedM197 := FALSE;
          g_bFinishedM197_0 := FALSE;
        END_IF;

      END_IF;    
  END_CASE;  
ELSE(*双IO*)
  CASE nClaw1ChangeState OF
    0:
      nClaw1ChangeState:=0;
    10:

      g_noClaw1GasControl :=FUN_pressureCovertAO(dSetGasPersent*g_nClawMaxPressure,g_nClawMaxPressure,g_nClawMaxVoltage);  
      IF  nClaw1ControlType =0 THEN   
        g_boClaw1UpDownClampEnable :=TRUE; 
        g_boClaw1UpDownLoosenEnable:= FALSE;
        bClaw1UpDownClampFlag := TRUE;
        bClaw1UpDownLoosenFlag := FALSE;
      ELSIF nClaw1ControlType =1 THEN 
        g_boClaw1UpDownClampEnable :=TRUE; 
        g_boClaw1UpDownLoosenEnable:= FALSE;
        bClaw1UpDownClampFlag := TRUE;
        bClaw1UpDownLoosenFlag := FALSE;
      ELSE
        g_boClaw1UpDownClampEnable :=FALSE; 
        g_boClaw1UpDownLoosenEnable:= TRUE;
        bClaw1UpDownClampFlag := FALSE;
        bClaw1UpDownLoosenFlag := TRUE;  
      END_IF;
      nClaw1ChangeState:=20; 
    20:
      Claw1ClampTon(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(g_dBackCardUpDownClampInplaceDelay)));
      IF Claw1ClampTon.Q THEN
        nClaw1ChangeState:=30;
        Claw1ClampTon(IN :=FALSE);
      END_IF;
    30: 
      IF  nClaw1ControlType =0 THEN   
        g_boClaw1LiftRightClampEnable :=TRUE;
        g_boClaw1LiftRightLoosenEnable :=FALSE;
        bClaw1LeftRightClampFlag := TRUE;
        bClaw1LeftRightLoosenFlag := FALSE;
      ELSIF nClaw1ControlType =1 THEN 
        g_boClaw1LiftRightClampEnable :=FALSE;
        g_boClaw1LiftRightLoosenEnable :=TRUE;
        bClaw1LeftRightClampFlag := FALSE;
        bClaw1LeftRightLoosenFlag := TRUE;
      ELSE
        g_boClaw1LiftRightClampEnable :=FALSE;
        g_boClaw1LiftRightLoosenEnable :=TRUE;
        bClaw1LeftRightClampFlag := FALSE;
        bClaw1LeftRightLoosenFlag := TRUE;  
      END_IF;
      bClaw1KeepPressureDone :=FALSE;
      nClaw1ChangeState := 40;
    40: 
      Claw1ClampTon(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(g_dBackCardLeftRightClampInplaceDelay)));
      IF Claw1ClampTon.Q THEN
        nClaw1ChangeState := 42;
        Claw1ClampTon(IN :=FALSE);
      END_IF;
    42:
      IF bKeepPressure THEN
        nClaw1KeepPressureState := 10; 
      ELSE
        bClaw1KeepPressureDone :=TRUE; 
      END_IF;
      nClaw1ChangeState := 43;  
    43:  
      IF bClaw1KeepPressureDone THEN
        nClaw1ChangeState := 45;  
      END_IF;  
    45:
      IF nClaw1ControlType =0 THEN 
        IF g_bBackCardUseLeftRightClampInplaceSignal AND g_bBackCardUseUpDownClampInplaceSignal THEN
          IF g_bUpDownClampedInPlaceClaw1 AND g_bLiftRightClampedInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylUpNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylUpNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE);
          END_IF;  
        ELSIF g_bBackCardUseUpDownClampInplaceSignal THEN
          IF g_bUpDownClampedInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylUpNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylUpNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE); 
          END_IF; 
        ELSIF g_bBackCardUseLeftRightClampInplaceSignal THEN
          IF g_bLiftRightClampedInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylUpNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylUpNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE); 
          END_IF; 
        ELSE
          nClaw1ChangeState:=150;
        END_IF; 
      ELSIF nClaw1ControlType =1 THEN  
        IF g_bBackCardUseLeftRightClampInplaceSignal AND g_bBackCardUseUpDownClampInplaceSignal THEN
          IF g_bUpDownClampedInPlaceClaw1 AND g_bLiftRightLossendInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylUpNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylUpNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE); 
          END_IF;  
        ELSIF g_bBackCardUseUpDownClampInplaceSignal THEN
          IF g_bUpDownClampedInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylUpNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylUpNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE); 
          END_IF; 
        ELSIF g_bBackCardUseLeftRightClampInplaceSignal THEN
          IF g_bLiftRightLossendInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylUpNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylUpNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE); 
          END_IF; 
        ELSE
          nClaw1ChangeState:=150;
        END_IF; 
      ELSIF nClaw1ControlType =2 THEN  
        IF g_bBackCardUseLeftRightClampInplaceSignal AND g_bBackCardUseUpDownClampInplaceSignal THEN
          IF g_bUpDownLossendInPlaceClaw1 AND g_bLiftRightLossendInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylUpNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylUpNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE); 
          END_IF;  
        ELSIF g_bBackCardUseUpDownClampInplaceSignal THEN
          IF g_bUpDownLossendInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylUpNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylUpNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE);    
          END_IF; 
        ELSIF g_bBackCardUseLeftRightClampInplaceSignal THEN
          IF g_bLiftRightLossendInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylUpNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylUpNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawUpDelayAlarm(IN := FALSE);     
          END_IF; 
        ELSE
          nClaw1ChangeState:=150;
        END_IF;  
      END_IF;
    50:
      g_noClaw1GasControl :=FUN_pressureCovertAO(g_nClawMaxPressure,g_nClawMaxPressure,g_nClawMaxVoltage);
      IF  nClaw1ControlType =0 THEN   
        g_boClaw1UpDownClampEnable:=FALSE;   
        g_boClaw1UpDownLoosenEnable :=TRUE;
        bClaw1UpDownClampFlag := FALSE;
        bClaw1UpDownLoosenFlag := TRUE;
      ELSIF nClaw1ControlType =1 THEN 
        g_boClaw1UpDownClampEnable:=FALSE;   
        g_boClaw1UpDownLoosenEnable :=TRUE;
        bClaw1UpDownClampFlag := FALSE;
        bClaw1UpDownLoosenFlag := TRUE;
      ELSE
        g_boClaw1UpDownClampEnable:=TRUE;   
        g_boClaw1UpDownLoosenEnable :=FALSE;
        bClaw1UpDownClampFlag := TRUE;
        bClaw1UpDownLoosenFlag := FALSE;
      END_IF;
      nClaw1ChangeState:=60; 
    60:
      Claw1InPlaceTon(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(g_dBackCardUpDownLossenInplaceDelay)));
      IF Claw1InPlaceTon.Q THEN
        nClaw1ChangeState := 70;
        Claw1InPlaceTon(IN :=FALSE);
      END_IF;
    70: 
      IF  nClaw1ControlType =0 THEN   
        g_boClaw1LiftRightClampEnable :=FALSE;
        g_boClaw1LiftRightLoosenEnable :=TRUE;
        bClaw1LeftRightClampFlag := FALSE;
        bClaw1LeftRightLoosenFlag := TRUE;
      ELSIF nClaw1ControlType =1 THEN 
        g_boClaw1LiftRightClampEnable :=TRUE;
        g_boClaw1LiftRightLoosenEnable :=FALSE;
        bClaw1LeftRightClampFlag := TRUE;
        bClaw1LeftRightLoosenFlag := FALSE;
      ELSE
        g_boClaw1LiftRightClampEnable :=TRUE;
        g_boClaw1LiftRightLoosenEnable :=FALSE;
        bClaw1LeftRightClampFlag := TRUE;
        bClaw1LeftRightLoosenFlag := FALSE;
      END_IF; 
      bClaw1KeepPressureDone :=FALSE;
      nClaw1ChangeState := 80; 
    80:
      Claw1InPlaceTon(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(g_dBackCardLeftRightLossenInplaceDelay)));
      IF Claw1InPlaceTon.Q THEN
        Claw1InPlaceTon(IN :=FALSE);
        nClaw1ChangeState:=82;
      END_IF; 
    82:
      IF bKeepPressure THEN
        nClaw1KeepPressureState := 10; 
      ELSE
        bClaw1KeepPressureDone :=TRUE; 
      END_IF;
      nClaw1ChangeState := 85;
    85:  
      IF bClaw1KeepPressureDone THEN
        nClaw1ChangeState := 90;  
      END_IF;    
    90:
      IF nClaw1ControlType =0 THEN 
        IF g_bBackCardUseUpDownLossenInplaceSignal AND g_bBackCardUseLeftRightLossenInplaceSignal THEN
          IF g_bUpDownLossendInPlaceClaw1 AND g_bLiftRightLossendInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylDownNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylDownNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);     
          END_IF;  
        ELSIF g_bBackCardUseUpDownLossenInplaceSignal THEN
          IF g_bUpDownLossendInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylDownNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylDownNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);  
          END_IF; 
        ELSIF g_bBackCardUseLeftRightLossenInplaceSignal THEN
          IF g_bLiftRightLossendInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylDownNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylDownNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);  
          END_IF; 
        ELSE
          nClaw1ChangeState:=150;
        END_IF; 
      ELSIF nClaw1ControlType =1 THEN  
        IF g_bBackCardUseUpDownLossenInplaceSignal AND g_bBackCardUseLeftRightLossenInplaceSignal THEN
          IF g_bUpDownLossendInPlaceClaw1 AND g_bLiftRightClampedInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylDownNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylDownNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);  
          END_IF;  
        ELSIF g_bBackCardUseUpDownLossenInplaceSignal THEN
          IF g_bUpDownLossendInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylDownNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylDownNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);  
          END_IF; 
        ELSIF g_bBackCardUseLeftRightLossenInplaceSignal THEN
          IF g_bLiftRightClampedInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylDownNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylDownNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);  
          END_IF; 
        ELSE
          nClaw1ChangeState:=150;
        END_IF; 
      ELSIF nClaw1ControlType =2 THEN  
        IF g_bBackCardUseUpDownLossenInplaceSignal AND g_bBackCardUseLeftRightLossenInplaceSignal THEN
          IF g_bUpDownClampedInPlaceClaw1 AND g_bLiftRightClampedInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylDownNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylDownNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);  
          END_IF;  
        ELSIF g_bBackCardUseUpDownLossenInplaceSignal THEN
          IF g_bUpDownClampedInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylDownNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylDownNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);  
          END_IF; 
        ELSIF g_bBackCardUseLeftRightLossenInplaceSignal THEN
          IF g_bLiftRightClampedInPlaceClaw1 THEN
            nClaw1ChangeState:=150;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);
            bForbidBackCardClawCylDownNoSignalAlarm:= FALSE;
          ELSE
            bForbidBackCardClawCylDownNoSignalAlarm:= TRUE;
            InPlaceForbidBackCardClawDownDelayAlarm(IN := FALSE);  
          END_IF; 
        ELSE
          nClaw1ChangeState:=150;
        END_IF;  
      END_IF;    

    150:  
      IF bClaw1KeepPressureDone THEN
        bClaw1KeepPressureDone :=FALSE;
        nClaw1ChangeState:=0;
        g_boClaw1Done:=TRUE;
        IF NOT g_bAllClawCylControlFlagM THEN
          M.ENABLE[197] := 0;
          g_bExecuteFinishedM197 := FALSE;
          g_bFinishedM197_0 := FALSE;
        END_IF;
      END_IF;    
  END_CASE; 
END_IF;  
CASE nClaw1KeepPressureState OF
  0:
  ;
  10:
    nTonClaw1Keep(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(nKeepPressureTime)));
    g_bKeepPressure1:= TRUE;
    IF nTonClaw1Keep.Q THEN
      nTonClaw1Keep(IN :=FALSE);
      g_boClaw1UpDownClampEnable:=FALSE;   
      g_boClaw1UpDownLoosenEnable :=FALSE;
      g_boClaw1LiftRightClampEnable :=FALSE;
      g_boClaw1LiftRightLoosenEnable :=FALSE;
      g_bKeepPressure1:= FALSE;
      bClaw1KeepPressureDone:= TRUE;
      nClaw1KeepPressureState:=0;
    END_IF;
END_CASE;  



(*卡爪2松紧开关*)
RtrigClaw2(CLK := ( g_bClaw2EnableM OR g_bClaw2Enable OR bClaw2Enable OR g_biClaw2Enable));
RtrigClaw2Off(CLK := ( g_bClaw2EnableOffM OR g_bClaw2EnableOff OR bClaw2EnableOff OR g_biClaw2EnableOff));
IF RtrigClaw2.Q THEN(*夹紧操作：先上下夹紧，延时时间后左右夹紧*)
  IF g_bAvoidEnable AND g_fCurrentCoordYBuffer >= g_fAvoidCoordY AND g_nAvoidType <= 1 THEN
    g_bClaw2EnableM := FALSE;
    g_bClaw2Enable:=FALSE;(*资源回收*)
    g_boClaw2Done:=TRUE;
    bClaw2Enable:=FALSE;
    IF NOT g_bAllClawCylControlFlagM THEN
      M.ENABLE[197] := 0;
      g_bExecuteFinishedM197 := FALSE;
      g_bFinishedM197_1 := FALSE;
    END_IF;
   RETURN; 
  END_IF;
  (*前卡禁止夹紧*)
  IF g_bForbidFrontCardClampExceedSetYPos AND g_fCurrentCoordYBuffer > g_dSetFrontCardYCoord THEN
    g_bClaw2EnableM := FALSE;
    g_bClaw2Enable:=FALSE;(*资源回收*)
    g_boClaw2Done:=TRUE;
    bClaw2Enable:=FALSE;
    IF NOT g_bAllClawCylControlFlagM THEN
      M.ENABLE[197] := 0;
      g_bExecuteFinishedM197 := FALSE;
      g_bFinishedM197_1 := FALSE;
    END_IF;
   RETURN; 
  END_IF;
  IF g_biClaw2Enable AND g_nPlcState = 1 THEN
    RETURN;
  END_IF;
  IF g_dM197SetKValue = 1.0 AND g_bFrontCardIsJiaJin THEN
	g_boClaw2Done:=TRUE;
		M.ENABLE[197] := 0;
		g_bExecuteFinishedM197 := FALSE;
		g_bFinishedM197_1 := FALSE;
        g_bClaw2EnableM := FALSE;
		g_bClaw2Enable:=FALSE;(*资源回收*)
		g_boClaw2Done:=TRUE;
		bClaw2Enable:=FALSE;
    RETURN;
  END_IF;
    nClaw2ChangeState:=10;
    g_bClaw2Enable:=FALSE;(*资源回收*)
    bClaw2Enable:=FALSE;
    nTonClaw2Keep(IN :=FALSE);
    g_boClaw2Done:=FALSE;
    g_bClaw2State:= TRUE;
    g_bClaw2EnableM := FALSE;
    bClaw2UpDownClampFlag := FALSE;
    bClaw2LeftRightClampFlag := FALSE;
    Claw2ClampTon(IN :=FALSE);
    nTonClaw2Keep(IN :=FALSE);
    bChuck2OperatedClamp := TRUE;
    InPlaceFrontClawDownDelayAlarm(IN := FALSE);
    bFrontClawCylDownNoSignalAlarm:= FALSE;
    bFrontClawCylUpFlag:= TRUE;
    bFrontClawCylDownFlag:= FALSE;
END_IF;
IF RtrigClaw2Off.Q THEN
  IF g_biClaw2EnableOff AND g_nPlcState = 1 THEN
    RETURN;
  END_IF;
   IF g_dM197SetKValue = 1.0 AND NOT g_bFrontCardIsJiaJin THEN
	g_boClaw2Done:=TRUE;
		M.ENABLE[197] := 0;
		g_bExecuteFinishedM197 := FALSE;
		g_bFinishedM197_1 := FALSE;
        g_bClaw2EnableOff:=FALSE;(*资源回收*)
		bClaw2EnableOff:=FALSE;
		g_bClaw2EnableOffM := FALSE; 
		g_boClaw2Done:=TRUE;
    RETURN;
  END_IF;
    nClaw2ChangeState:=50;
    g_bClaw2EnableOff:=FALSE;(*资源回收*)
    bClaw2EnableOff:=FALSE;
    nTonClaw2Keep(IN :=FALSE);
    g_boClaw2Done:=FALSE;
    g_bClaw2State:= FALSE;
    g_bClaw2EnableOffM := FALSE; 
    bClaw2UpDownLoosenFlag :=FALSE;
    bClaw2LeftRightLoosenFlag := FALSE;
    Claw2InPlaceTon(IN :=FALSE);
    nTonClaw2Keep(IN :=FALSE);
    InPlaceFrontClawUpDelayAlarm(IN := FALSE);
    bFrontClawCylUpNoSignalAlarm:= FALSE;
    bFrontClawCylUpFlag:= FALSE;
    bFrontClawCylDownFlag:= TRUE;
END_IF;

(*单io *)
IF g_nClamp1ControlType = 1 THEN
  CASE nClaw2ChangeState OF
    0:
      nClaw2ChangeState:=0;
    10:
      g_noClaw2GasControl :=FUN_pressureCovertAO(dSetGasPersent*g_nClawMaxPressure,g_nClawMaxPressure,g_nClawMaxVoltage);    
      g_boClaw2UpDownClampEnable :=TRUE; 
      g_boClaw2UpDownLoosenEnable:= FALSE;
      IF bKeepPressure1 THEN
        bClaw2KeepPressureDone :=FALSE;
        nClaw2KeepPressureState := 10; 
      ELSE
        bClaw2KeepPressureDone :=TRUE; 
      END_IF;
      nClaw2ChangeState:=20; 
      bClaw2UpDownClampFlag := TRUE;
      bClaw2UpDownLoosenFlag := FALSE;
    20:
      IF g_bFrontCardUseUpDownClampInplaceSignal THEN
        IF g_bUpDownClampedInPlaceClaw2 THEN  
          nClaw2ChangeState:=150;
          InPlaceFrontClawUpDelayAlarm(IN := FALSE);
          bFrontClawCylUpNoSignalAlarm:= FALSE;
        ELSE
          IF NOT g_bFrontClawState THEN
            InPlaceFrontClawUpDelayAlarm(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_dFrontCardUpDownClampInplaceDelay)));
            IF InPlaceFrontClawUpDelayAlarm.Q THEN
              bFrontClawCylUpNoSignalAlarm:= TRUE;
              InPlaceFrontClawUpDelayAlarm(IN := FALSE);
            END_IF;
          ELSE
            bFrontClawCylUpNoSignalAlarm:= TRUE;
            InPlaceFrontClawUpDelayAlarm(IN := FALSE);     
          END_IF; 
        END_IF;
      ELSE
        InPlaceFrontClawUpDelayAlarm(IN := FALSE);
        bFrontClawCylUpNoSignalAlarm:= FALSE;
        Claw2ClampTon(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(g_dFrontCardUpDownClampInplaceDelay)));
        IF Claw2ClampTon.Q THEN
          nClaw2ChangeState:=150;
          Claw2ClampTon(IN :=FALSE);
        END_IF;
      END_IF;
    50:
      g_noClaw2GasControl :=FUN_pressureCovertAO(g_nClawMaxPressure,g_nClawMaxPressure,g_nClawMaxVoltage);
      g_boClaw2UpDownClampEnable:=FALSE;   
      g_boClaw2UpDownLoosenEnable :=TRUE;
      IF bKeepPressure1 THEN
        bClaw2KeepPressureDone :=FALSE;
        nClaw2KeepPressureState := 10;
      ELSE
        bClaw2KeepPressureDone :=TRUE;   
      END_IF; 
      nClaw2ChangeState:=60; 
      bClaw2UpDownClampFlag := FALSE;
      bClaw2UpDownLoosenFlag := TRUE;
    60:
      IF g_bFrontCardUseUpDownLossenInplaceSignal OR (g_no2AvoidState = 215 AND g_nChuckOpenCheckType = 2) THEN
        IF g_bUpDownLossendInPlaceClaw2 THEN
          nClaw2ChangeState := 150;
          InPlaceFrontClawDownDelayAlarm(IN := FALSE);
          bFrontClawCylDownNoSignalAlarm:= FALSE;
        ELSE
          IF g_bFrontClawState THEN
            InPlaceFrontClawDownDelayAlarm(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_dFrontCardUpDownLossenInplaceDelay)));
            IF InPlaceFrontClawDownDelayAlarm.Q THEN
              bFrontClawCylDownNoSignalAlarm:= TRUE;
              InPlaceFrontClawDownDelayAlarm(IN := FALSE);  
            END_IF;   
          ELSE
            bFrontClawCylDownNoSignalAlarm:= TRUE;
            InPlaceFrontClawDownDelayAlarm(IN := FALSE);   
          END_IF; 
        END_IF;
      ELSE  
        InPlaceFrontClawDownDelayAlarm(IN := FALSE);
        bFrontClawCylDownNoSignalAlarm:= FALSE;
        Claw2InPlaceTon(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(g_dFrontCardUpDownLossenInplaceDelay)));
        IF Claw2InPlaceTon.Q THEN
          nClaw2ChangeState := 150;
          Claw2InPlaceTon(IN :=FALSE);
        END_IF;
      END_IF;  
    150:  
      IF bClaw2KeepPressureDone THEN
        bClaw2KeepPressureDone :=FALSE;
        nClaw2ChangeState:=0;
        g_boClaw2Done:=TRUE;
        IF NOT g_bAllClawCylControlFlagM THEN
          M.ENABLE[197] := 0;
          g_bExecuteFinishedM197 := FALSE;
          g_bFinishedM197_1 := FALSE;
        END_IF;
      END_IF;    
  END_CASE;  
ELSE(*双IO*)
  CASE nClaw2ChangeState OF
    0:
      nClaw2ChangeState:=0;
    10:

      g_noClaw2GasControl :=FUN_pressureCovertAO(dSetGasPersent*g_nClawMaxPressure,g_nClawMaxPressure,g_nClawMaxVoltage);  
      IF  nClaw2ControlType =0 THEN   
        g_boClaw2UpDownClampEnable :=TRUE; 
        g_boClaw2UpDownLoosenEnable:= FALSE;
        bClaw2UpDownClampFlag := TRUE;
        bClaw2UpDownLoosenFlag := FALSE;
      ELSIF nClaw2ControlType =1 THEN 
        g_boClaw2UpDownClampEnable :=TRUE; 
        g_boClaw2UpDownLoosenEnable:= FALSE;
        bClaw2UpDownClampFlag := TRUE;
        bClaw2UpDownLoosenFlag := FALSE;
      ELSE
        g_boClaw2UpDownClampEnable :=FALSE; 
        g_boClaw2UpDownLoosenEnable:= TRUE;
        bClaw2UpDownClampFlag := FALSE;
        bClaw2UpDownLoosenFlag := TRUE;  
      END_IF;
      nClaw2ChangeState:=20; 
    20:
      Claw2ClampTon(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(g_dFrontCardUpDownClampInplaceDelay)));
      IF Claw2ClampTon.Q THEN
        nClaw2ChangeState:=30;
        Claw2ClampTon(IN :=FALSE);
      END_IF;
    30: 
      IF  nClaw2ControlType =0 THEN   
        g_boClaw2LiftRightClampEnable :=TRUE;
        g_boClaw2LiftRightLoosenEnable :=FALSE;
        bClaw2LeftRightClampFlag := TRUE;
        bClaw2LeftRightLoosenFlag := FALSE;
      ELSIF nClaw2ControlType =1 THEN 
        g_boClaw2LiftRightClampEnable :=FALSE;
        g_boClaw2LiftRightLoosenEnable :=TRUE;
        bClaw2LeftRightClampFlag := FALSE;
        bClaw2LeftRightLoosenFlag := TRUE;
      ELSE
        g_boClaw2LiftRightClampEnable :=FALSE;
        g_boClaw2LiftRightLoosenEnable :=TRUE;
        bClaw2LeftRightClampFlag := FALSE;
        bClaw2LeftRightLoosenFlag := TRUE;  
      END_IF;
      bClaw2KeepPressureDone :=FALSE;
      nClaw2ChangeState := 40;
    40: 
      Claw2ClampTon(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(g_dFrontCardLeftRightClampInplaceDelay)));
      IF Claw2ClampTon.Q THEN
        nClaw2ChangeState := 42;
        Claw2ClampTon(IN :=FALSE);
      END_IF;
    42:
      IF bKeepPressure1 THEN
        nClaw2KeepPressureState := 10; 
      ELSE
        bClaw2KeepPressureDone :=TRUE; 
      END_IF;  
      nClaw2ChangeState := 43;
    43:  
      IF bClaw2KeepPressureDone THEN
        nClaw2ChangeState := 45;
      END_IF;  
    45:
      IF nClaw2ControlType =0 THEN 
        IF g_bFrontCardUseLeftRightClampInplaceSignal AND g_bFrontCardUseUpDownClampInplaceSignal THEN
          IF g_bUpDownClampedInPlaceClaw2 AND g_bLiftRightClampedInPlaceClaw2 THEN
            nClaw2ChangeState:=150;
            InPlaceFrontClawUpDelayAlarm(IN := FALSE);
            bFrontClawCylUpNoSignalAlarm:= FALSE;
          ELSE
            IF NOT g_bFrontClawState THEN
              InPlaceFrontClawUpDelayAlarm(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_dFrontCardUpDownClampInplaceDelay)));
              IF InPlaceFrontClawUpDelayAlarm.Q THEN
                bFrontClawCylUpNoSignalAlarm:= TRUE;
                InPlaceFrontClawUpDelayAlarm(IN := FALSE);
              END_IF;
            ELSE
              bFrontClawCylUpNoSignalAlarm:= TRUE;
              InPlaceFrontClawUpDelayAlarm(IN := FALSE);     
            END_IF;  
          END_IF;  
        ELSIF g_bFrontCardUseUpDownClampInplaceSignal THEN
          IF g_bUpDownClampedInPlaceClaw2 THEN
            nClaw2ChangeState:=150;
            InPlaceFrontClawUpDelayAlarm(IN := FALSE);
            bFrontClawCylUpNoSignalAlarm:= FALSE;
          ELSE
            IF NOT g_bFrontClawState THEN
              InPlaceFrontClawUpDelayAlarm(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_dFrontCardUpDownClampInplaceDelay)));
              IF InPlaceFrontClawUpDelayAlarm.Q THEN
                bFrontClawCylUpNoSignalAlarm:= TRUE;
                InPlaceFrontClawUpDelayAlarm(IN := FALSE);
              END_IF;
            ELSE
              bFrontClawCylUpNoSignalAlarm:= TRUE;
              InPlaceFrontClawUpDelayAlarm(IN := FALSE);     
            END_IF; 
          END_IF; 
        ELSIF g_bFrontCardUseLeftRightClampInplaceSignal THEN
          IF g_bLiftRightClampedInPlaceClaw2 THEN
            nClaw2ChangeState:=150;
            InPlaceFrontClawUpDelayAlarm(IN := FALSE);
            bFrontClawCylUpNoSignalAlarm:= FALSE;
          ELSE
            IF NOT g_bFrontClawState THEN
              InPlaceFrontClawUpDelayAlarm(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_dFrontCardUpDownClampInplaceDelay)));
              IF InPlaceFrontClawUpDelayAlarm.Q THEN
                bFrontClawCylUpNoSignalAlarm:= TRUE;
                InPlaceFrontClawUpDelayAlarm(IN := FALSE);
              END_IF;
            ELSE
              bFrontClawCylUpNoSignalAlarm:= TRUE;
              InPlaceFrontClawUpDelayAlarm(IN := FALSE);     
            END_IF; 
          END_IF; 
        ELSE
          nClaw2ChangeState:=150;
        END_IF; 
      ELSIF nClaw2ControlType =1 THEN  
        IF g_bFrontCardUseLeftRightClampInplaceSignal AND g_bFrontCardUseUpDownClampInplaceSignal THEN
          IF g_bUpDownClampedInPlaceClaw2 AND g_bLiftRightLossendInPlaceClaw2 THEN
            nClaw2ChangeState:=150;
            InPlaceFrontClawUpDelayAlarm(IN := FALSE);
            bFrontClawCylUpNoSignalAlarm:= FALSE;
          ELSE
            IF NOT g_bFrontClawState THEN
              InPlaceFrontClawUpDelayAlarm(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_dFrontCardUpDownClampInplaceDelay)));
              IF InPlaceFrontClawUpDelayAlarm.Q THEN
                bFrontClawCylUpNoSignalAlarm:= TRUE;
                InPlaceFrontClawUpDelayAlarm(IN := FALSE);
              END_IF;
            ELSE
              bFrontClawCylUpNoSignalAlarm:= TRUE;
              InPlaceFrontClawUpDelayAlarm(IN := FALSE);     
            END_IF;
          END_IF;  
        ELSIF g_bFrontCardUseUpDownClampInplaceSignal THEN
          IF g_bUpDownClampedInPlaceClaw2 THEN
            nClaw2ChangeState:=150;
            InPlaceFrontClawUpDelayAlarm(IN := FALSE);
            bFrontClawCylUpNoSignalAlarm:= FALSE;
          ELSE
            IF NOT g_bFrontClawState THEN
              InPlaceFrontClawUpDelayAlarm(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_dFrontCardUpDownClampInplaceDelay)));
              IF InPlaceFrontClawUpDelayAlarm.Q THEN
                bFrontClawCylUpNoSignalAlarm:= TRUE;
                InPlaceFrontClawUpDelayAlarm(IN := FALSE);
              END_IF;
            ELSE
              bFrontClawCylUpNoSignalAlarm:= TRUE;
              InPlaceFrontClawUpDelayAlarm(IN := FALSE);     
            END_IF;
          END_IF; 
        ELSIF g_bFrontCardUseLeftRightClampInplaceSignal THEN
          IF g_bLiftRightLossendInPlaceClaw2 THEN
            nClaw2ChangeState:=150;
            InPlaceFrontClawUpDelayAlarm(IN := FALSE);
            bFrontClawCylUpNoSignalAlarm:= FALSE;
          ELSE
            IF NOT g_bFrontClawState THEN
              InPlaceFrontClawUpDelayAlarm(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_dFrontCardUpDownClampInplaceDelay)));
              IF InPlaceFrontClawUpDelayAlarm.Q THEN
                bFrontClawCylUpNoSignalAlarm:= TRUE;
                InPlaceFrontClawUpDelayAlarm(IN := FALSE);
              END_IF;
            ELSE
              bFrontClawCylUpNoSignalAlarm:= TRUE;
              InPlaceFrontClawUpDelayAlarm(IN := FALSE);     
            END_IF;
          END_IF; 
        ELSE
          nClaw2ChangeState:=150;
        END_IF; 
      ELSIF nClaw2ControlType =2 THEN  
        IF g_bFrontCardUseLeftRightClampInplaceSignal AND g_bFrontCardUseUpDownClampInplaceSignal THEN
          IF g_bUpDownLossendInPlaceClaw2 AND g_bLiftRightLossendInPlaceClaw2 THEN
            nClaw2ChangeState:=150;
            InPlaceFrontClawUpDelayAlarm(IN := FALSE);
            bFrontClawCylUpNoSignalAlarm:= FALSE;
          ELSE
            IF NOT g_bFrontClawState THEN
              InPlaceFrontClawUpDelayAlarm(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_dFrontCardUpDownClampInplaceDelay)));
              IF InPlaceFrontClawUpDelayAlarm.Q THEN
                bFrontClawCylUpNoSignalAlarm:= TRUE;
                InPlaceFrontClawUpDelayAlarm(IN := FALSE);
              END_IF;
            ELSE
              bFrontClawCylUpNoSignalAlarm:= TRUE;
              InPlaceFrontClawUpDelayAlarm(IN := FALSE);     
            END_IF;
          END_IF;  
        ELSIF g_bFrontCardUseUpDownClampInplaceSignal THEN
          IF g_bUpDownLossendInPlaceClaw2 THEN
