    150:  
      IF bClaw2KeepPressureDone THEN
        bClaw2KeepPressureDone :=FALSE;
        nClaw2ChangeState:=0;
        g_boClaw2Done:=TRUE;
        IF NOT g_bAllClawCylControlFlagM THEN
          M.ENABLE[197] := 0;
          g_bExecuteFinishedM197 := FALSE;
          g_bFinishedM197_1 := FALSE;
        END_IF;
      END_IF;    
  END_CASE; 
