CASE nClaw2KeepPressureState OF
  0:
  ;
  10:
    nTonClaw2Keep(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(nKeepPressureTime1)));
    g_bKeepPressure2:= TRUE;
    IF nTonClaw2Keep.Q THEN
      nTonClaw2Keep(IN :=FALSE);
      g_boClaw2UpDownClampEnable:=FALSE;   
      g_boClaw2UpDownLoosenEnable :=FALSE;
      g_boClaw2LiftRightClampEnable :=FALSE;
      g_boClaw2LiftRightLoosenEnable :=FALSE;
      g_bKeepPressure2:= FALSE;
      bClaw2KeepPressureDone:= TRUE;
      nClaw2KeepPressureState:=0;
    END_IF;
END_CASE;  


(*卡爪3松紧开关*)
RtrigClaw3(CLK := ( g_bClaw3EnableM OR g_bClaw3Enable OR bClaw3Enable));
RtrigClaw3Off(CLK := ( g_bClaw3EnableOffM OR g_bClaw3EnableOff OR bClaw3EnableOff));
IF RtrigClaw3.Q THEN(*夹紧操作：先上下夹紧，延时时间后左右夹紧*)
  nClaw3ChangeState:=10;
  g_bClaw3Enable:=FALSE;(*资源回收*)
  bClaw3Enable:=FALSE;
  nTonClaw3Keep(IN :=FALSE);
  g_boClaw3Done:=FALSE;
  g_bClaw3State:= TRUE;
  g_bClaw3EnableM := FALSE;
END_IF;
IF RtrigClaw3Off.Q THEN
  nClaw3ChangeState:=20;
  g_bClaw3EnableOff:=FALSE;(*资源回收*)
  bClaw3EnableOff:=FALSE;
  nTonClaw3Keep(IN :=FALSE);
  g_boClaw3Done:=FALSE;
  g_bClaw3State:= FALSE;
  g_bClaw3EnableOffM := FALSE;
END_IF;
(*卡爪3状态*)
IF nClaw3ControlType = 0 THEN
  CASE nClaw3ChangeState OF
    0:
      nClaw3ChangeState:=0;
    10:(*上下夹紧*)
      g_noClaw3GasControl :=FUN_pressureCovertAO(dSetGasPersent*g_nClawMaxPressure,g_nClawMaxPressure,g_nClawMaxVoltage);    
      g_boClaw3UpDownClampEnable :=TRUE; 
      g_boClaw3UpDownLoosenEnable:= FALSE;

      Claw3ClampTon(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(g_nClaw3ClampTimeSpan)));

      IF Claw3ClampTon.Q THEN
        nClaw3ChangeState:=12;

      END_IF;
    12:(*左右夹紧*)
      Claw3ClampTon(IN :=FALSE);
      g_boClaw3LiftRightClampEnable :=TRUE;
      g_boClaw3LiftRightLoosenEnable :=FALSE;
      IF g_bUseClaw3ClampPosition THEN(*使用气缸到位信号*)
        IF  g_bUpDownClampedInPlaceClaw3 AND  g_bLiftRightClampedInPlaceClaw3 THEN
          IF bKeepPressure2 THEN
            nClaw3ChangeState:=14;
          ELSE
            nClaw3ChangeState:=0;
            g_boClaw3Done:=TRUE;
            IF NOT g_bAllClawCylControlFlagM THEN
              M.ENABLE[197] := 0;
              g_bExecuteFinishedM197 := FALSE;
              g_bFinishedM197_2 := FALSE;
            END_IF;
          END_IF;
        END_IF;
      ELSE
        IF bKeepPressure2 THEN
          nClaw3ChangeState:=14;
        ELSE
          Claw3InPlaceTon(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(nClaw3InPlaceDelay)));

          IF Claw3InPlaceTon.Q THEN

            nClaw3ChangeState:=0;

            g_boClaw3Done:=TRUE;

            Claw3InPlaceTon(IN :=FALSE);
            IF NOT g_bAllClawCylControlFlagM THEN
              M.ENABLE[197] := 0;
              g_bExecuteFinishedM197 := FALSE;
