      g_bClaw4IsJiajin := TRUE;
    END_IF;
    IF g_boClaw4UpDownLoosen AND g_boClaw4LeftRightLoosen AND g_boClaw4UpDownClamp=FALSE AND g_boClaw4LeftRightClamp=FALSE THEN
      g_bClaw4Status := FALSE;
      g_bClaw4IsJiajin := FALSE;
    END_IF;
  ELSIF nClaw3ControlType = 1 THEN
    IF g_bUpDownClampedInPlaceClaw4 AND g_bLiftRightLossendInPlaceClaw4 THEN
      g_bClaw4Status :=TRUE;
      g_bClaw4IsJiajin := TRUE;
    END_IF;
    IF g_boClaw4UpDownLoosen AND g_boClaw4LeftRightLoosen=FALSE AND g_boClaw4UpDownClamp=FALSE AND g_boClaw4LeftRightClamp THEN
      g_bClaw4Status := FALSE;
      g_bClaw4IsJiajin := FALSE;
    END_IF;
  ELSE
    IF g_bUpDownLossendInPlaceClaw4 AND g_bLiftRightLossendInPlaceClaw4 THEN
      g_bClaw4Status :=TRUE;
      g_bClaw4IsJiajin := TRUE;
    END_IF;
    IF g_boClaw4UpDownLoosen=FALSE AND g_boClaw4LeftRightLoosen=FALSE AND g_boClaw4UpDownClamp AND g_boClaw4LeftRightClamp THEN
      g_bClaw4Status := FALSE;
      g_bClaw4IsJiajin := FALSE;
    END_IF; 
  END_IF;  
ELSE
  (*卡爪4指示灯状态*)
  IF nClaw4ControlType = 0 THEN
    IF g_boClaw4UpDownClamp AND g_boClaw4LeftRightClamp AND g_boClaw4UpDownLoosen=FALSE AND g_boClaw4LeftRightLoosen=FALSE THEN
      g_bClaw4Status := TRUE;
      g_bClaw4IsJiajin := TRUE;
    END_IF;
    IF g_bUpDownLossendInPlaceClaw4 AND g_bLiftRightLossendInPlaceClaw4 THEN
      g_bClaw4Status :=FALSE;
      g_bClaw4IsJiajin := FALSE;
    END_IF;
  ELSIF nClaw3ControlType = 1 THEN
    IF g_boClaw4UpDownClamp AND g_boClaw4LeftRightClamp=FALSE AND g_boClaw4UpDownLoosen=FALSE AND g_boClaw4LeftRightLoosen THEN
      g_bClaw4Status := TRUE;
      g_bClaw4IsJiajin := TRUE;
    END_IF;
    IF g_bUpDownLossendInPlaceClaw4 AND g_bLiftRightClampedInPlaceClaw4 THEN
      g_bClaw4Status :=FALSE;
      g_bClaw4IsJiajin := FALSE;
    END_IF;
  ELSE
    IF g_boClaw4UpDownClamp=FALSE AND g_boClaw4LeftRightClamp=FALSE AND g_boClaw4UpDownLoosen AND g_boClaw4LeftRightLoosen THEN
      g_bClaw4Status := TRUE;
      g_bClaw4IsJiajin := TRUE;
    END_IF;
    IF g_bUpDownClampedInPlaceClaw4 AND g_bLiftRightClampedInPlaceClaw4 THEN
      g_bClaw4Status :=FALSE;
      g_bClaw4IsJiajin := FALSE;
    END_IF;
  END_IF;  
END_IF;

