    g_bClylinder12State := FALSE;
    IF g_bCloseOutputAfterOperationDone THEN
      g_boSupportcyLinder12DownEnable := FALSE;
    END_IF;
    bSupportCylDownNoSignalAlarm12:= FALSE;
    InPlaceSupportDownDelayAlarm12(IN := FALSE);
  ELSE 
    IF g_bClylinder12State THEN
      InPlaceSupportDownDelayAlarm12(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_dClylinder12DownDoneTime)));
      IF InPlaceSupportDownDelayAlarm12.Q THEN
        bSupportCylDownNoSignalAlarm12:= TRUE;
        InPlaceSupportDownDelayAlarm12(IN := FALSE);
      END_IF;   
    END_IF;    
  END_IF;
  IF NOT g_bClylinder12State AND g_CylAllStateUpDate.BoolArr[101] THEN
    bSupportCylDownNoSignalAlarm12:= FALSE;
    InPlaceSupportDownDelayAlarm12(IN := FALSE);
  ELSIF NOT g_bClylinder12State AND NOT g_CylAllStateUpDate.BoolArr[101] THEN
    bSupportCylDownNoSignalAlarm12:= TRUE;
    InPlaceSupportDownDelayAlarm12(IN := FALSE);
  END_IF; 
ELSIF g_bSupportCylinder12DelayFlag THEN
  bSupportCylDownNoSignalAlarm12:= FALSE;
  InPlaceSupportDownDelayAlarm12(IN := FALSE);
  bSupportCylUpNoSignalAlarm12:= FALSE;
  InPlaceSupportUpDelayAlarm12(IN := FALSE);
  IF g_boSupportcyLinder12UpEnable THEN
    InDownPlaceDelay12(IN := FALSE);
    InPlaceDelay12(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_dClylinder12UpDoneTime)));
  ELSIF g_boSupportcyLinder12DownEnable THEN
    InPlaceDelay12(IN := FALSE);
    InDownPlaceDelay12(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_dClylinder12DownDoneTime)));
  END_IF;
  IF InPlaceDelay12.Q OR InDownPlaceDelay12.Q THEN
    g_bSupportCylinder12DelayFlag := FALSE;
    InPlaceDelay12(IN := FALSE);
    InDownPlaceDelay12(IN := FALSE);
    IF g_boSupportcyLinder12UpEnable AND NOT g_boSupportcyLinder12DownEnable THEN
      g_bClylinder12State := TRUE;
      IF g_bCloseOutputAfterOperationDone THEN
        g_boSupportcyLinder12UpEnable := FALSE;
      END_IF;
    END_IF;
    IF g_boSupportcyLinder12DownEnable AND NOT g_boSupportcyLinder12UpEnable THEN
      g_bClylinder12State := FALSE;
      IF g_bCloseOutputAfterOperationDone THEN
        g_boSupportcyLinder12DownEnable := FALSE;
      END_IF;
    END_IF;
  END_IF;
END_IF;
