(*卡盘气缸一键控制*)
RtringAllControl(CLK := g_bAllClawCylControlM);
IF RtringAllControl.Q THEN
  g_bAllClawCylControlM := FALSE;
  nAllClawCylState := 10;
END_IF;
CASE nAllClawCylState OF
  0:
  nAllClawCylState := 0;
  10:
  (*控制卡盘气缸一键上升或者下降*)
    g_bAllClawCylControlFlagM := TRUE;  
    IF g_dAllClawCylControlTypeM = 1.0 THEN
      g_bClaw1EnableM := TRUE;
      g_bClaw2EnableM := TRUE;
      g_bClaw3EnableM := TRUE;
    ELSIF g_dAllClawCylControlTypeM = 0.0 THEN
      g_bClaw1EnableOffM := TRUE;
      g_bClaw2EnableOffM := TRUE;
      g_bClaw3EnableOffM := TRUE;  
    END_IF;
    g_boClaw1Done:= FALSE;
    g_boClaw2Done:= FALSE;
    g_boClaw3Done:= FALSE;
    nAllClawCylState := 15; 
  15:
    g_bExecuteFinishedM197 := TRUE;
    IF g_boClaw1Done AND g_boClaw2Done AND g_boClaw3Done THEN
      bCheckClawFlag := TRUE; 
    ELSE
      bCheckClawFlag := FALSE;  
    END_IF;  
    IF bCheckClawFlag THEN
      nAllClawCylState := 40;
    END_IF;
  40:
    bCheckClawFlag := FALSE;
    bALLClawClawFlag := FALSE; 
    nAllClawCylState := 0;
    M.ENABLE[197] := 0;
    g_bExecuteFinishedM197 := FALSE;
    g_bFinishedM197_10 := FALSE;
END_CASE;


