 (*保存卡盘状态,每次状态改变一下才去保存*)
 IF bHMIChange THEN
		IF NOT bKeepPressure THEN
          g_bBackCardIsJiaJin := FALSE;
          g_bBackClawState := FALSE;
        END_IF; 

        IF NOT bKeepPressure1  THEN
          g_bFrontClawState := FALSE;
          g_bFrontCardIsJiaJin := FALSE;
        END_IF; 

        IF NOT bKeepPressure2  THEN
          g_bMiddleClawState := FALSE;
        END_IF; 

        IF NOT bKeepPressure3  THEN
          g_bClaw4Status := FALSE;
        END_IF; 
    bHMIChange := FALSE;
  END_IF;



  Claw1SaveState(CLK := g_bBackClawState);
  Claw1SaveState1(CLK := g_bFrontClawState);
  Claw1SaveState2(CLK := g_bMiddleClawState);
  Claw1SaveState3(CLK := g_bClaw4Status);
  FClaw1State(CLK := g_bBackClawState);
  FClaw1State1(CLK := g_bFrontClawState);
  FClaw1State2(CLK := g_bMiddleClawState);
  FClaw1State3(CLK := g_bClaw4Status); 
  bClaw1SaveStateFlag := (Claw1SaveState.Q OR FClaw1State.Q) ;
  bClaw2SaveStateFlag := (Claw1SaveState1.Q OR FClaw1State1.Q) ;
  bClaw3SaveStateFlag := (Claw1SaveState2.Q OR FClaw1State2.Q);
  bClaw4SaveStateFlag := (Claw1SaveState3.Q OR FClaw1State3.Q);


  IF bClaw1SaveStateFlag OR bClaw2SaveStateFlag OR bClaw3SaveStateFlag OR bClaw4SaveStateFlag THEN
    ClawStateSave(ENABLE := TRUE);
  END_IF;

   g_bClaw1State :=  g_bBackCardIsJiaJin; 
   g_bClaw2State :=  g_bFrontCardIsJiaJin;      

IF g_bPlcResetBuffer OR g_bPlcEndM THEN
  nAllClawCylState := 0;
  g_bExecuteFinishedM197 := FALSE;
  g_bFinishedM197_0 := FALSE;
  g_bFinishedM197_1 := FALSE;
  g_bFinishedM197_2 := FALSE;
  g_bFinishedM197_10 := FALSE;  
END_IF;
